contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint16 _feeRate, uint256 _inputAmount) public {
        require(_feeRate <= 5_000);
        require(_inputAmount > 0 && _inputAmount < 1e18);

        c.initialize(
            address(0),
            address(1),
            1e18,
            1e18,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(_inputAmount);

        assert(
            feeAmount == (_inputAmount * 1e18 / (1e18 + _inputAmount)) * uint256(c.feeRate()) / 10_000
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint16 _feeRate, uint256 _outputAmount) public {
        require(_feeRate <= 5_000);
        require(_outputAmount > 0 && _outputAmount < 1e18);

        c.initialize(
            address(0),
            address(1),
            1e18,
            1e18,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(_outputAmount);

        uint256 inputAmount = (_outputAmount * 1e18) / (1e18 - _outputAmount);

        assert(
            feeAmount == (inputAmount * uint256(c.feeRate())) / 10_000 &&
            protocolFeeAmount == 0 &&
            netInputAmount == inputAmount + feeAmount + protocolFeeAmount
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, bytes memory data) public {
        // fresh pool: this contract (msg.sender) is not the owner of the pool NFT,
        // so execute() must revert Unauthorized regardless of target/data.
        bool reverted;
        bytes memory d = data;
        address t = target;
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSelector(c.execute.selector, t, d));
        reverted = !ok;
        assert(reverted);
    }
    receive() external payable {}
}

