contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        address bt,
        address nft,
        uint128 vb,
        uint128 vn,
        uint56 cf,
        uint16 fr,
        bytes32 mr,
        bool uo,
        bool pr
    ) public {
        bool ok1;
        try c.initialize(bt, nft, vb, vn, cf, fr, mr, uo, pr) { ok1 = true; } catch { ok1 = false; }
        bool ok2;
        try c.initialize(bt, nft, vb, vn, cf, fr, mr, uo, pr) { ok2 = true; } catch { ok2 = false; }
        if (fr <= 5000) {
            assert(
                ok1 && !ok2 &&
                c.initialized() &&
                c.baseToken() == bt &&
                c.nft() == nft &&
                c.virtualBaseTokenReserves() == vb &&
                c.virtualNftReserves() == vn &&
                c.changeFee() == cf &&
                c.feeRate() == fr &&
                c.merkleRoot() == mr &&
                c.useStolenNftOracle() == uo &&
                c.payRoyalties() == pr
            );
        } else {
            assert(!ok1 && !ok2 && !c.initialized());
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 vb,
        uint128 vn,
        uint16 fr,
        uint256 a
    ) public {
        require(fr <= 5000, "feeRate too high");
        require(a > 0, "empty sell");

        c.initialize(address(0), address(0), vb, vn, 0, fr, bytes32(0), false, false);

        (uint256 netOutput, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(a);

        uint256 outputAmount = a * uint256(vb) / (uint256(vn) + a);

        assert(
            feeAmount == outputAmount * fr / 10000 &&
            netOutput + feeAmount + protocolFeeAmount == outputAmount &&
            netOutput <= outputAmount
        );
    }

    receive() external payable {}
}
